changeSet.sql:
ALTER TABLE whiteboard.whiteboard_asset_cleanup
    DROP CONSTRAINT whiteboard_asset_cleanup_storage_key_ck;
ALTER TABLE whiteboard.whiteboard_asset_cleanup
    ADD CONSTRAINT whiteboard_asset_cleanup_storage_key_ck CHECK (
        length(storage_key) <= 512 AND (
            storage_key LIKE 'whiteboard-v2-assets/%'
            OR (reason = 'board_deleted' AND storage_key ~ ('^whiteboard-assets/' || page_id::text || '/sha256/[0-9a-f]{64}$'))
        )
    );

rollback.sql:
ALTER TABLE whiteboard.whiteboard_asset_cleanup
    DROP CONSTRAINT whiteboard_asset_cleanup_storage_key_ck;
ALTER TABLE whiteboard.whiteboard_asset_cleanup
    ADD CONSTRAINT whiteboard_asset_cleanup_storage_key_ck CHECK (
        storage_key LIKE 'whiteboard-v2-assets/%' AND length(storage_key) <= 512
    );
